// Offline start from the service worker (src/sw.js, generated by scripts/build.mjs): after one
// online visit the precached shell boots without network, still cross-origin isolated and under
// the current CSP (the cached page keeps the headers of scripts/headers.json), and the on-device
// workspace keeps answering from an attached file without any AI model.
import { headersFor, resolveHeaderRules } from '../../scripts/lib/headers.mjs';
import { expect, mockSupabase, test } from './fixtures.mjs';

// The suite blocks service workers by default (playwright.config.mjs); this file is about them.
test.use({ serviceWorkers: 'allow' });

const ISOLATED = { crossOriginIsolated: true, sharedArrayBuffer: true };
/** What the browser logs while the network is gone (the update check, the knowledge base). */
const OFFLINE_FAILURE = /^console\.error: Failed to load resource: net::ERR_INTERNET_DISCONNECTED$/;

/** Self-contained: serialized into the page. */
function isolationProbe() {
  let sharedArrayBuffer = false;
  try {
    sharedArrayBuffer = new SharedArrayBuffer(8).byteLength === 8;
  } catch {
    // not isolated
  }
  return { crossOriginIsolated: globalThis.crossOriginIsolated === true, sharedArrayBuffer };
}

/** @param {import('@playwright/test').Page} page @param {string} tab */
async function openTab(page, tab) {
  const isMobile = (page.viewportSize()?.width ?? 1280) < 768;
  await page.click(isMobile ? `#mobile-nav-${tab}` : `#nav-${tab}`);
  await expect(page.locator(`#tab-${tab}`)).toBeVisible();
}

test('serves the shell offline after the first visit, isolated, under the current headers, and keeps answering', async ({ page, context, diagnostics }) => {
  await mockSupabase(page, { hardened: true, anonymousAuth: true });
  const manifest = await (await page.request.get('/build-manifest.json')).json();
  const expected = headersFor(resolveHeaderRules(manifest.profile), '/');

  // Online: the worker installs, precaches the shell of this build and takes control of the page.
  await page.goto('/');
  await expect(page.locator('#dbStatusBadge')).toHaveText('Live');
  await page.evaluate(() => navigator.serviceWorker.ready);
  await expect.poll(() => page.evaluate(() => navigator.serviceWorker.controller?.state ?? null)).toBe('activated');
  const cached = await page.evaluate(
    (name) => caches.open(name).then((cache) => cache.keys()).then((keys) => keys.map((r) => new URL(r.url).pathname)),
    `starpi-shell-${manifest.version}`,
  );
  expect(new Set(cached)).toEqual(new Set(manifest.precache));

  // Offline: no network at all, the knowledge base unreachable as well.
  await context.setOffline(true);
  await page.route(/^https:\/\/[a-z0-9]+\.supabase\.co\//, (route) => route.abort('internetdisconnected'));
  const response = await page.reload();
  expect(response?.fromServiceWorker(), 'the page comes from the service worker').toBe(true);
  const headers = response?.headers() ?? {};
  for (const { key, value } of expected.values()) expect(headers[key.toLowerCase()], `offline page: ${key}`).toBe(value);
  await expect(page.locator('#dbStatusBadge')).toHaveText('Offline');
  expect(await page.evaluate(isolationProbe)).toEqual(ISOLATED);

  // Still usable: the views switch, and the precached ingest worker indexes a file that answers.
  for (const tab of ['library', 'ingest', 'settings', 'chat']) await openTab(page, tab);
  await page.setInputFiles('#chatFileInput', { name: 'offline-notes.md', mimeType: 'text/markdown', buffer: Buffer.from('# Offline notes\n\nThe offline drill takes place on 4 June.') });
  await expect(page.locator('#attachedFileName')).toHaveText('offline-notes.md · 1 chunk');
  await page.fill('#chatInput', 'When does the offline drill take place?');
  await page.press('#chatInput', 'Enter');
  const answer = page.locator('#chatMessages > div').last();
  await expect(answer).toContainText('4 June');
  await expect(answer).toContainText('no AI model was used');

  diagnostics.splice(0, diagnostics.length, ...diagnostics.filter((d) => !OFFLINE_FAILURE.test(d)));
  expect(diagnostics).toEqual([]);
});
